        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                     if r in (r0,r1) or c in (c0,c1)}
        if set(cells) == perimeter and r1-r0 >= 2 and c1-c0 >= 2:
            frames.append((color,r0,r1,c0,c1))
            frame_cells.update(perimeter)

    # Dots outside frames are clues. Each frame's clue color is the color
    # whose dots are closest to the frame center (rather than to its border).
    clues = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r,c) not in frame_cells:
                clues.setdefault(color, []).append((r,c))

    for color, r0, r1, c0, c1 in frames:
        center = ((r0+r1)/2, (c0+c1)/2)
        best = None
        for clue_color, pts in clues.items():
            if clue_color == color:
                continue
            # The typical clue is the nearest individual dot to the center.
            dist = min((r-center[0])**2 + (c-center[1])**2 for r,c in pts)
            if best is None or dist < best[0]:
                best = (dist, clue_color)
        fill = best[1] if best else 0

        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = color
                elif (r-r0-1 + c-c0-1) % 2 == 0:
                    out[r][c] = fill
    return out
